	}

	@Test public void rosterUrlAllowsExplicitJVMOverrideWithoutBundledProperties()
	{
		String previous = System.getProperty("holyempire.rosterBaseUrl");
		try
		{
			System.setProperty("holyempire.rosterBaseUrl", " http://127.0.0.1:18765 ");
